// Conformance suite for Opening Cross clearing (`opening-cross/conformance/v1`).
//
// The vectors in `conformance/v1.json` are generated by clearing-core, the implementation that
// runs on chain. Any implementation of ADR-0003 — a verifier, an indexer, a UI preview, another
// chain's port — passes only if it reproduces every case exactly: print or no print with the
// reason, the clearing price, matched volume, rationed side and each order's fill.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { type RefOrder, referenceClear, referenceFills } from './reference.js';

export const CONFORMANCE_SCHEMA = 'opening-cross/conformance/v1';

export type ConformanceCase = {
  name: string;
  grid: { min: string; tick: string; ticks: number };
  reference: string | null;
  guards: { minMatched: string; maxImbalanceBps: number | null };
  orders: { side: 'buy' | 'sell'; price: string; quantity: string }[];
  expect:
    | { printed: false; noPrintReason: 'NoCross' | 'BelowMinimumVolume' | 'ImbalanceTooHigh'; wouldClearAt?: string }
    | { printed: true; price: string; matched: string; rationed: 'none' | 'buy' | 'sell'; fills: string[] };
};
export type ConformanceVectors = { schema: string; cases: ConformanceCase[] };

/** What an implementation returns for one case, in the same shape as `expect`. */
export type ConformanceResult = ConformanceCase['expect'];
export type Implementation = (c: ConformanceCase) => ConformanceResult;

export function loadVectors(path = fileURLToPath(new URL('../conformance/v1.json', import.meta.url))): ConformanceVectors {
  const v = JSON.parse(readFileSync(path, 'utf8')) as ConformanceVectors;
  if (v.schema !== CONFORMANCE_SCHEMA) throw new Error(`unexpected schema ${v.schema}`);
  return v;
}

/** Runs an implementation over every case; returns the cases it got wrong (empty = conformant). */
export function runConformance(vectors: ConformanceVectors, impl: Implementation): { name: string; expected: ConformanceResult; actual: ConformanceResult | string }[] {
  const failures: { name: string; expected: ConformanceResult; actual: ConformanceResult | string }[] = [];
  for (const c of vectors.cases) {
    let actual: ConformanceResult | string;
    try {
      actual = impl(c);
    } catch (e) {
      actual = `threw: ${e instanceof Error ? e.message : String(e)}`;
    }
    if (typeof actual === 'string' || canonical(actual) !== canonical(c.expect)) failures.push({ name: c.name, expected: c.expect, actual });
  }
  return failures;
}

const canonical = (r: ConformanceResult) =>
  r.printed
    ? JSON.stringify([true, r.price, r.matched, r.rationed, r.fills])
    : JSON.stringify([false, r.noPrintReason, r.wouldClearAt ?? null]);

/** The verifier's own implementation: the independent TypeScript reference plus the print guards. */
export const referenceImplementation: Implementation = (c) => {
  const orders: RefOrder[] = c.orders.map((o) => ({ side: o.side, price: BigInt(o.price), quantity: BigInt(o.quantity) }));
  const r = referenceClear(orders, { min: BigInt(c.grid.min), tick: BigInt(c.grid.tick), ticks: c.grid.ticks }, c.reference === null ? null : BigInt(c.reference));
  if (!r) return { printed: false, noPrintReason: 'NoCross' };
  if (r.matched < BigInt(c.guards.minMatched)) return { printed: false, noPrintReason: 'BelowMinimumVolume', wouldClearAt: r.price.toString() };
  if (c.guards.maxImbalanceBps !== null) {
    let d = 0n;
    let s = 0n;
    for (const o of orders) {
      if (o.side === 'buy' && o.price >= r.price) d += o.quantity;
      if (o.side === 'sell' && o.price <= r.price) s += o.quantity;
    }
    const imbalance = d > s ? d - s : s - d;
    if (imbalance * 10_000n > BigInt(c.guards.maxImbalanceBps) * r.matched) return { printed: false, noPrintReason: 'ImbalanceTooHigh', wouldClearAt: r.price.toString() };
  }
  return { printed: true, price: r.price.toString(), matched: r.matched.toString(), rationed: r.rationed ?? 'none', fills: referenceFills(orders, r).map(String) };
};
